import math

def softmax(values):
    peak = max(values)
    weights = [math.exp(v-peak) for v in values]
    return [w/sum(weights) for w in weights]

def norm(x, eps=1e-5):
    mean = sum(x)/len(x)
    variance = sum((v-mean)**2 for v in x)/len(x)
    return [(v-mean)/math.sqrt(variance+eps) for v in x]

def affine(x, weights, bias):
    return [sum(x[i]*weights[i][j] for i in range(len(x)))+bias[j] for j in range(len(bias))]

class Solution:
    def attention(self, query: list[float], keys: list[list[float]], values: list[list[float]]) -> list[float]:
        weights=softmax([sum(a*b for a,b in zip(query,key))/math.sqrt(len(query)) for key in keys])
        return [sum(weights[i]*values[i][j] for i in range(len(values))) for j in range(len(values[0]))]

